package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashSet;
import java.util.Iterator;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.apache.commons.jxpath.ri.context.EvalContext;
import org.apache.commons.jxpath.ri.expression.Expression;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CoreOperationCompare_equal_TriageGen1Test {

    private CoreOperationCompare compare;
    private EvalContext mockContext;
    private Expression mockLeft;
    private Expression mockRight;

    // Mocking types used in the method logic
    interface InitialContext extends EvalContext {}
    interface SelfContext extends EvalContext {}

    @Before
    public void setUp() {
        // The constructor requires two expressions, but we are testing the protected equal method
        // We use a dummy approach to instantiate the class under test
        mockContext = mock(EvalContext.class);
        mockLeft = mock(Expression.class);
        mockRight = mock(Expression.class);

        // Using a subclass to expose the protected method for testing
        compare = new CoreOperationCompare(mockLeft, mockRight) {
            @Override
            public boolean equal(EvalContext context, Expression left, Expression right) {
                return super.equal(context, left, right);
            }
        };
    }

    /**
     * Helper to create a spy of CoreOperationCompare to mock the recursive equal(Object, Object)
     * and the contains/findMatch methods which are part of the same class.
     */
    private CoreOperationCompare createSpyCompare() {
        return spy(new CoreOperationCompare(mockLeft, mockRight) {
            @Override
            public boolean equal(EvalContext context, Expression left, Expression right) {
                return super.equal(context, left, right);
            }
        });
    }

    @Test
    public void testEqual_BasicObjects() {
        compare = createSpyCompare();
        when(mockLeft.compute(mockContext)).thenReturn("A");
        when(mockRight.compute(mockContext)).thenReturn("A");
        doReturn(true).when(compare).equal("A", "A");

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_NullObjects() {
        compare = createSpyCompare();
        when(mockLeft.compute(mockContext)).thenReturn(null);
        when(mockRight.compute(mockContext)).thenReturn(null);
        doReturn(true).when(compare).equal(null, null);

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_LeftIsInitialContext() {
        compare = createSpyCompare();
        InitialContext ic = mock(InitialContext.class);
        Object pointer = "pointer";
        when(ic.getSingleNodePointer()).thenReturn(pointer);

        when(mockLeft.compute(mockContext)).thenReturn(ic);
        when(mockRight.compute(mockContext)).thenReturn("val");

        // After context conversion, l becomes pointer
        doReturn(true).when(compare).equal(pointer, "val");

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_RightIsSelfContext() {
        compare = createSpyCompare();
        SelfContext sc = mock(SelfContext.class);
        Object pointer = "pointer";
        when(sc.getSingleNodePointer()).thenReturn(pointer);

        when(mockLeft.compute(mockContext)).thenReturn("val");
        when(mockRight.compute(mockContext)).thenReturn(sc);

        doReturn(true).when(compare).equal("val", pointer);

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_LeftIsCollection() {
        compare = createSpyCompare();
        List<String> list = Arrays.asList("A", "B");
        Iterator<String> it = list.iterator();

        when(mockLeft.compute(mockContext)).thenReturn(list);
        when(mockRight.compute(mockContext)).thenReturn("A");

        // l becomes iterator, r is Object -> calls contains(it, "A")
        doReturn(true).when(compare).contains(it, "A");

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_RightIsCollection() {
        compare = createSpyCompare();
        List<String> list = Arrays.asList("A", "B");
        Iterator<String> it = list.iterator();

        when(mockLeft.compute(mockContext)).thenReturn("A");
        when(mockRight.compute(mockContext)).thenReturn(list);

        // r becomes iterator, l is Object -> calls contains(it, "A")
        doReturn(true).when(compare).contains(it, "A");

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_BothAreIterators() {
        compare = createSpyCompare();
        List<String> list1 = Arrays.asList("A");
        List<String> list2 = Arrays.asList("A");
        Iterator<String> it1 = list1.iterator();
        Iterator<String> it2 = list2.iterator();

        when(mockLeft.compute(mockContext)).thenReturn(it1);
        when(mockRight.compute(mockContext)).thenReturn(it2);

        // Both are iterators -> calls findMatch(it1, it2)
        doReturn(true).when(compare).findMatch(it1, it2);

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_LeftIsIteratorRightIsNot() {
        compare = createSpyCompare();
        Iterator<String> it = Collections.singletonList("A").iterator();

        when(mockLeft.compute(mockContext)).thenReturn(it);
        when(mockRight.compute(mockContext)).thenReturn("A");

        doReturn(true).when(compare).contains(it, "A");

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_RightIsIteratorLeftIsNot() {
        compare = createSpyCompare();
        Iterator<String> it = Collections.singletonList("A").iterator();

        when(mockLeft.compute(mockContext)).thenReturn("A");
        when(mockRight.compute(mockContext)).thenReturn(it);

        doReturn(true).when(compare).contains(it, "A");

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_MixedContextAndCollection() {
        compare = createSpyCompare();
        InitialContext ic = mock(InitialContext.class);
        List<String> list = Arrays.asList("A");
        Iterator<String> it = list.iterator();

        when(ic.getSingleNodePointer()).thenReturn("pointer");
        when(mockLeft.compute(mockContext)).thenReturn(ic);
        when(mockRight.compute(mockContext)).thenReturn(list);

        // l becomes "pointer", r becomes iterator -> calls contains(it, "pointer")
        doReturn(false).when(compare).contains(it, "pointer");

        assertFalse(compare.equal(mockContext, mockLeft, mockRight));
    }
}
